import React from 'react';
import MainHeading from '../../Components/Heading/MainHeading';
import NavBar from '../../Components/NavBar/NavBar';
import bgVideo from "./back.mp4"
import solarImage from "./solar.webp"


function Home() {
  return (
    <>
    <div className="relative w-full h-screen">
    {/* Background video */}
    <video
      className="absolute top-0 left-0 w-full h-full object-cover"
      autoPlay
      loop
      muted
      >
      <source src={bgVideo} type="video/mp4" />
      Your browser does not support the video tag.
    </video>

    {/* Overlay content */}
    <div className="relative font-poppins z-10  items-center justify-center flex w-full h-full bg-transparent bg-opacity-50">
      <NavBar  />
      <h1 className="text-white text-7xl font-bold">Explore The Solar System</h1>
      {/* <p className="mt-4 text-lg">Journey through the wonders of the Sun, planets, and beyond.</p> */}
    </div>
  </div>
  {/* s2 */}
  <div className=" h-full">
    <h1>Over</h1>
    <img src={solarImage} alt="" srcset="" />
    <p>The solar system is a vast collection of celestial objects bound together by the Sun's gravitational pull. At its center is the Sun, a massive, energy-producing star that provides light and heat to its surrounding planets. These planets are divided into rocky terrestrial worlds like Mercury, Venus, Earth, and Mars, and gas or ice giants like Jupiter, Saturn, Uranus, and Neptune. Alongside these are smaller bodies such as dwarf planets like Pluto, countless moons, asteroids in the asteroid belt, and icy comets from regions like the Kuiper Belt and the distant Oort Cloud. The solar system also contains meteoroids, cosmic dust, and the solar wind, all existing in the vast interplanetary space that extends up to 100,000 astronomical units from the Sun. This intricate system, spanning immense distances, is a dynamic and ever-evolving part of the universe.</p>
  </div>
      </>
  );
}

export default Home;
